def write_project(target: Path):
    target = target.resolve(); target.mkdir(parents=True, exist_ok=True)
    for rel, data in FILES_B64.items():
        p = target / Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(data))
    print(f"[{APP_NAME}] v{APP_VERSION} written to: {target}")
    return target

def install_and_run(target: Path, project=None):
    venv = target / ".venv"
    if not venv.exists():
        r=subprocess.run([sys.executable,"-m","venv",str(venv)], check=False)
        if r.returncode: return r.returncode
    py=venv/('Scripts/python.exe' if sys.platform.startswith('win') else 'bin/python')
    subprocess.run([str(py),"-m","pip","install","-r",str(target/"requirements.txt")],check=False)
    cmd=[str(py),str(target/"main.py")]
    if project: cmd += ["--project",str(Path(project).resolve())]
    return subprocess.call(cmd)

def main():
    ap=argparse.ArgumentParser(prog="bootstrap_studio.py")
    ap.add_argument("--target",default=str(DEFAULT_TARGET))
    ap.add_argument("--install",action="store_true")
    ap.add_argument("--run",action="store_true")
    ap.add_argument("--project",default=None)
    ns=ap.parse_args()
    target=write_project(Path(ns.target))
    if ns.install or ns.run: return install_and_run(target,ns.project)
    print("Next: run.bat [--project PATH] or python main.py --project PATH")
    return 0

if __name__ == "__main__": raise SystemExit(main())
